/* The public cancellation guide pages, generated by tools/build-guides.mjs from
   lib/cancellation-guides.ts and served at /cancel/<slug> and
   /de/kuendigen/<slug>.

   Reads the generated files and the source rather than executing the
   TypeScript, so it runs anywhere. What it guards:
   - every published page has a checked date in the data, because each page
     prints "last checked" and an unchecked guide would make that untrue;
   - the generated output matches the manifest the server reads, in both
     languages, so a slug never routes to a missing file;
   - the server only serves slugs from the manifest (an allowlist), so a
     request cannot name another file in that directory;
   - the German pages are actually German: German quotes, German button text,
     German legal links, not the English ones.
   Measured separately on 2026-10-11: the routes driven through a real Express
   app (200 for the five slugs and both indexes in each language, 404 for an
   unknown slug, an encoded traversal and the manifest itself), the sitemap
   emitting 12 URLs, and every page rendered in Chromium at 360, 390 and 1280
   wide with Montserrat loaded and no sideways scroll. */

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const read = (...p) => fs.readFileSync(path.join(ROOT, ...p), "utf8");
const GUIDES_DIR = path.join(ROOT, "backend", "guides");
const manifest = JSON.parse(read("backend", "guides", "manifest.json"));
const DATA = read("lib", "cancellation-guides.ts");
const SERVER = read("backend", "server.js");

describe("cancellation guide pages", () => {
  it("publishes at least one guide and every slug is URL safe", () => {
    expect(manifest.guides.length).toBeGreaterThan(0);
    for (const g of manifest.guides) {
      expect(g.slug).toMatch(/^[a-z0-9-]+$/);
      expect(g.lastmod).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    }
  });

  it("has a page per slug in both languages, plus an index each", () => {
    for (const lang of ["en", "de"]) {
      const files = fs.readdirSync(path.join(GUIDES_DIR, lang)).sort();
      const expected = [...manifest.guides.map((g) => `${g.slug}.html`), "index.html"].sort();
      expect(files).toEqual(expected);
    }
  });

  it("prints a checked date that matches the data, never one invented by the build", () => {
    const dates = [...DATA.matchAll(/verified: "(\d{4}-\d{2}-\d{2})"/g)].map((m) => m[1]);
    for (const g of manifest.guides) expect(dates).toContain(g.lastmod);
    const de = read("backend", "guides", "de", "netflix.html");
    expect(de).toMatch(/Zuletzt geprüft am \d{1,2}\. [A-ZÄÖÜ][a-zäöü]+ \d{4}/);
    const en = read("backend", "guides", "en", "netflix.html");
    expect(en).toMatch(/Last checked \d{1,2} [A-Z][a-z]+ \d{4}/);
  });

  it("no published guide is more than six months past its last check", () => {
    /* DELIBERATELY TIED TO TODAY. Every page prints "last checked", and a
       service changes its cancel flow without telling anybody, so a guide
       older than six months is a public claim nobody stands behind. When this
       fails on a commit that touched nothing here, that is the alarm working:
       re-check the named guide against the service's help page and move its
       verified date, or take it off PAGES in tools/build-guides.mjs. Do not
       freeze the clock to make it pass. */
    const SIX_MONTHS = 183 * 86400000;
    const stale = manifest.guides
      .filter((g) => Date.now() - Date.parse(g.lastmod + "T00:00:00Z") > SIX_MONTHS)
      .map((g) => `${g.slug} last checked ${g.lastmod}`);
    expect(stale).toEqual([]);
  });

  it("the build refuses a guide without a checked date", () => {
    const build = read("tools", "build-guides.mjs");
    expect(build).toMatch(/has no verified date/);
  });

  it("serves only slugs from the manifest", () => {
    expect(SERVER).toMatch(/GUIDE_SET\.has\(req\.params\.slug\)/);
    const routes = SERVER.match(/app\.get\('\/(?:de\/kuendigen|cancel)\/:slug'[^\n]*/g) || [];
    expect(routes.length).toBe(2);
    for (const r of routes) expect(r).toMatch(/GUIDE_SET\.has/);
  });

  it("lists every guide in the sitemap with its language pair", () => {
    expect(SERVER).toMatch(/guideSitemapEntries\(\)/);
    expect(SERVER).toMatch(/hreflang="de" href="\$\{SITE\}\$\{de\}"/);
  });

  it("German pages read as German", () => {
    for (const g of manifest.guides) {
      const html = read("backend", "guides", "de", `${g.slug}.html`);
      expect(html).toMatch(/<html lang="de">/);
      expect(html).toMatch(/kündigen/);
      expect(html).toMatch(/href="\/de\/datenschutz"/);
      expect(html).not.toMatch(/href="\/privacy-policy"/);
      expect(html).not.toMatch(/Vienna/);
      // Straight quotes from the data become German quotes on the page.
      const steps = html.slice(html.indexOf('<ol class="steps"'), html.indexOf("</ol>"));
      expect(steps).not.toMatch(/&quot;/);
    }
  });

  it("each page has a canonical and both language alternates", () => {
    for (const lang of ["en", "de"]) {
      for (const g of manifest.guides) {
        const html = read("backend", "guides", lang, `${g.slug}.html`);
        const own = lang === "de" ? `/de/kuendigen/${g.slug}` : `/cancel/${g.slug}`;
        expect(html).toContain(`<link rel="canonical" href="https://www.subtrimio.com${own}" />`);
        expect(html).toContain(`hreflang="en" href="https://www.subtrimio.com/cancel/${g.slug}"`);
        expect(html).toContain(`hreflang="de" href="https://www.subtrimio.com/de/kuendigen/${g.slug}"`);
      }
    }
  });

  it("the landing footers link into the guides", () => {
    expect(read("backend", "landing.html")).toMatch(/href="\/cancel">Cancellation guides</);
    expect(read("backend", "landing-de.html")).toMatch(/href="\/de\/kuendigen">Kündigungsanleitungen</);
  });

  it("the German Amazon guide sends readers to amazon.de, not amazon.com", () => {
    const html = read("backend", "guides", "de", "amazon-prime.html");
    expect(html).toMatch(/href="https:\/\/www\.amazon\.de\//);
    expect(html).not.toMatch(/href="https:\/\/www\.amazon\.com\//);
  });
});
